30	const PROCESSING_FEE = 5;
31	
32	/**
33	 * The spec keeps intermediate amounts as exact fractions and rounds only the
34	 * final amount. Binary floating point cannot do that: `100 * 1.1` is
35	 * 110.00000000000001, which rounds *up* to 111 instead of 110.
36	 *
37	 * So percentages are applied as integer rationals — multiply by the numerator
38	 * first, divide by the denominator last — and money is carried in hundredths
39	 * of a G. Both operands of every product stay integral, so no drift accrues.
40	 */
41	const SUBUNITS_PER_G = 100;
42	const toSubunits = (gold: number): number => Math.round(gold * SUBUNITS_PER_G);
43	
44	/** A percentage as an exact rational, e.g. +10 % is { num: 110, den: 100 }. */
45	interface Rate {
46	  num: number;
47	  den: number;
48	}
49	
50	const FIRST_INSURANCE_SURCHARGE: Rate = { num: 110, den: 100 };
51	
52	const applyRate = (subunits: number, rate: Rate): number => (subunits * rate.num) / rate.den;
53	
54	/** Premiums round up — in the MHPCO's favour. */
55	const toPremiumGold = (subunits: number): number => Math.ceil(subunits / SUBUNITS_PER_G);
56	
57	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_ITEM_TYPE[item.type] ?? 0;
67	
68	/** Exactly this many alike components form a block, priced as one unit. */
69	const COMPONENT_BLOCK_SIZE = 3;
70	const COMPONENT_BLOCK_PREMIUM = 60;
71	
72	const formsComponentBlock = (items: Item[]): boolean =>
73	  items.length === COMPONENT_BLOCK_SIZE && items.every((item) => item.type === "rune");
74	
75	const sumOfBasePremiums = (items: Item[]): number =>
76	  items.reduce((total, item) => total + basePremiumOf(item), 0);
77	
78	/**
79	 * The policy base premium: every insured item's base premium, summed — except
80	 * that a block of alike components is priced as one unit instead.
81	 */
82	const policyBasePremiumOf = (items: Item[]): number =>
83	  formsComponentBlock(items) ? COMPONENT_BLOCK_PREMIUM : sumOfBasePremiums(items);
84	
85	const quotePremium = (items: Item[]): number => {
86	  const policyBase = toSubunits(policyBasePremiumOf(items));
87	
88	  return toPremiumGold(applyRate(policyBase, FIRST_INSURANCE_SURCHARGE) + toSubunits(PROCESSING_FEE));
89	};
90	
91	export const runScenario = (scenario: Scenario): ScenarioResults => {
92	  return { results: scenario.steps.map((step) => ({ premium: quotePremium(step.items) })) };
93	};
