const COMPONENT_TYPES = ["rune", "moonstone"];

const isComponent = (item: Item): boolean => COMPONENT_TYPES.includes(item.type);

/** Components are alike when they are of the very same type. */
const areAlike = (items: Item[]): boolean =>
  items.every((item) => item.type === items[0].type);

/** Exactly this many alike components form a block, priced as one unit. */
const COMPONENT_BLOCK_SIZE = 3;
const COMPONENT_BLOCK_PREMIUM = 60;

const formsComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE && items.every(isComponent) && areAlike(items);
